import { pdfjs } from "./pdfjs";
import { filterPii, piiTaxonomy } from "./pii-rules";
import {
  applyCustomRules,
  type PiiCustomRule,
  type PiiMatch,
} from "./redaction-policy";

export type PdfVerificationReport = {
  schemaVersion: 1;
  scope: "extractable-text-only";
  status: "residual-matches" | "no-text-matches" | "no-extractable-text";
  outputSha256: string;
  pageCount: number;
  pagesWithText: number;
  residualMatchCount: number;
  residuals: { page: number; kind: string; count: number }[];
  limitations: string[];
};

/** Read the generated bytes, not the original document or its cached text.
 * No matched values, file names or original document text enter the report.
 */
export async function verifyExportedPdf(
  bytes: Uint8Array,
  {
    selectedMatches = [],
    customRules = [],
  }: { selectedMatches?: PiiMatch[]; customRules?: PiiCustomRule[] } = {},
): Promise<PdfVerificationReport> {
  const hash = await crypto.subtle.digest(
    "SHA-256",
    Uint8Array.from(bytes).buffer,
  );
  // pdf.js can transfer/detach its input, so never pass the caller's export buffer.
  const task = pdfjs.getDocument({ data: Uint8Array.from(bytes) });
  try {
    const document = await task.promise;
    const pages: string[] = [];
    for (let index = 1; index <= document.numPages; index++) {
      const page = await document.getPage(index);
      const content = await page.getTextContent();
      pages.push(
        content.items.map((item) => ("str" in item ? item.str : "")).join(" "),
      );
    }
    return scanExportedText(
      pages,
      selectedMatches,
      customRules,
      [...new Uint8Array(hash)]
        .map((n) => n.toString(16).padStart(2, "0"))
        .join(""),
    );
  } finally {
    await task.destroy();
  }
}

export function scanExportedText(
  pages: string[],
  selectedMatches: PiiMatch[],
  customRules: PiiCustomRule[],
  outputSha256: string,
): PdfVerificationReport {
  const residuals: PdfVerificationReport["residuals"] = [];
  let pagesWithText = 0;
  pages.forEach((text, index) => {
    if (text.trim()) pagesWithText++;
    const candidates = [
      ...filterPii(text).matches,
      ...applyCustomRules(text, customRules),
    ];
    for (const selected of selectedMatches) {
      if (!selected.value) continue;
      let offset = 0;
      while ((offset = text.indexOf(selected.value, offset)) >= 0) {
        candidates.push({
          ...selected,
          start: offset,
          end: offset + selected.value.length,
        });
        offset += selected.value.length;
      }
    }
    const unique = new Map(
      candidates.map((m) => [`${m.kind}:${m.start}:${m.end}`, m]),
    );
    const byKind = new Map<string, number>();
    for (const match of unique.values()) {
      // Never echo a user-provided rule name into the report either.
      const kind = piiTaxonomy.includes(match.kind) ? match.kind : "custom";
      byKind.set(kind, (byKind.get(kind) ?? 0) + 1);
    }
    for (const [kind, count] of byKind)
      residuals.push({ page: index + 1, kind, count });
  });
  const residualMatchCount = residuals.reduce(
    (sum, item) => sum + item.count,
    0,
  );
  return {
    schemaVersion: 1,
    scope: "extractable-text-only",
    status: residualMatchCount
      ? "residual-matches"
      : pagesWithText
        ? "no-text-matches"
        : "no-extractable-text",
    outputSha256,
    pageCount: pages.length,
    pagesWithText,
    residualMatchCount,
    residuals,
    limitations: [
      "This is not proof that the PDF contains no PII.",
      "No OCR or visual inspection of rasterized pages was performed.",
      "Metadata, attachments, annotations and hidden objects were not inspected.",
      "Built-in regex rules, custom rules and exact selected source values only; no ONNX rescan.",
      "PDF text extraction may split or normalize text and miss a source value.",
    ],
  };
}
